function todayKyiv(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const o=Object.fromEntries(p.map(x=>[x.type,x.value]));return `${o.year}-${o.month}-${o.day}`}
const fmtDate=v=>{if(!v)return '—';const d=new Date(v.length===10?v+'T00:00:00':v);return isNaN(d)?v:d.toLocaleDateString('ru-RU')};
const fmtDateTime=v=>{if(!v)return '—';const d=new Date(v);return isNaN(d)?v:d.toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'})};
const money=v=>v===''||v==null?'—':`${Number(String(v).replace(',','.')).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})} грн`;
function humanBytes(n){n=Number(n||0);if(n<1024)return `${n} Б`;const u=['КБ','МБ','ГБ','ТБ'];let i=-1;do{n/=1024;i++}while(n>=1024&&i<u.length-1);return `${n.toLocaleString('ru-RU',{maximumFractionDigits:n>=100?0:n>=10?1:2})} ${u[i]}`}
function toast(text,bad=false){const t=$('#toast');t.textContent=text;t.classList.toggle('bad',bad);t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),3000)}
function setBusy(btn,busy,label='Подождите…'){if(!btn)return;if(busy){btn.dataset.oldText=btn.textContent;btn.textContent=label;btn.disabled=true}else{btn.textContent=btn.dataset.oldText||btn.textContent;btn.disabled=false}}
