function uiKind(kind){return kind==='evaluation'?'eval':kind}
function allowedRegionCodes(){if(['owner','boss'].includes(currentUser?.role))return Object.keys(REGIONS);const list=Array.isArray(currentUser?.regions)?currentUser.regions.filter(Boolean):[];if(list.length)return list;if(currentUser?.region&&currentUser.region!=='all')return [currentUser.region];return []}
