function recordDisplayId(r){const rg=REGIONS[r.region]?.code?.toUpperCase()||'RG';const k=r.kind==='eval'?'EV':r.kind.toUpperCase();return `${rg}-${String(r.date||'').replaceAll('-','')}-${k}-${String(r.id||'').slice(0,6).toUpperCase()}`}

function formatMoneyValue(raw){
  let s=String(raw??'').trim().replace(/\s/g,'').replace(',','.').replace(/[^0-9.-]/g,'');
  if(!s||s==='-'||Number.isNaN(Number(s)))return '0,00';
  return Number(s).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2,useGrouping:false});
}
function moneyNumber(v){const n=Number(String(v??0).replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)?n:0}
function moneyField(name,label,value=''){return `<label>${label}<div class="money-wrap"><input class="money-entry" name="${name}" inputmode="decimal" value="${esc(value||'0,00')}"><span>грн</span></div></label>`}
