async function loadBootstrap(){
  const {data:regions,error:rErr}=await sb.from('regions').select('id,name,code,is_active').eq('is_active',true).order('name');
  if(rErr)throw rErr;
  REGIONS={};REGION_BY_UUID={};
  for(const r of regions||[]){const code=r.code||r.name.toLowerCase();const item={...r,code,eyebrow:r.name.toUpperCase()};REGIONS[code]=item;REGION_BY_UUID[r.id]=item}
  const {data:types,error:tErr}=await sb.from('violation_types').select('id,region_id,category,name,is_active').eq('is_active',true).order('name');
  if(tErr)throw tErr;
  VIOLATION_TYPES={cat1:(types||[]).filter(x=>x.category===1),cat2:(types||[]).filter(x=>x.category===2)};
  if(!VIOLATION_TYPES.cat1.length)VIOLATION_TYPES.cat1=FALLBACK_CAT1.map(name=>({name}));
  if(!VIOLATION_TYPES.cat2.length)VIOLATION_TYPES.cat2=FALLBACK_CAT2.map(name=>({name}));
}
async function loadProfile(){
  const {data:{user},error:uErr}=await sb.auth.getUser();if(uErr||!user)return null;
  const {data:p,error}=await sb.from('profiles').select('id,username,full_name,role,region_id,is_active,created_at').eq('id',user.id).single();
  if(error||!p||!p.is_active)return null;
  let regionIds=[];
  if(['senior','operator'].includes(p.role)){
    const {data:links,error:lErr}=await sb.from('user_regions').select('region_id').eq('user_id',user.id);
    if(lErr)throw lErr;
    regionIds=[...new Set((links||[]).map(x=>x.region_id).filter(Boolean))];
    if(!regionIds.length&&p.region_id)regionIds=[p.region_id];
  }
  const regions=regionIds.map(regionCodeFromUuid).filter(Boolean);
  const region=['owner','boss'].includes(p.role)?'all':(regions[0]||(p.region_id?regionCodeFromUuid(p.region_id):null));
  return {id:p.id,login:p.username,name:p.full_name,role:p.role,region,regionId:p.region_id,regions,regionIds,active:p.is_active};
}
