async function fetchAllPaged(buildQuery,pageSize=1000,maxRows=50000){let out=[];for(let start=0;start<maxRows;start+=pageSize){const q=buildQuery().range(start,start+pageSize-1);const {data,error}=await q;if(error)throw error;out.push(...(data||[]));if(!data||data.length<pageSize)break}return out}
function scopedRecordsQuery(q){const regionSel=$('#regionSelect')?.value||'all';if(regionSel!=='all')q=q.eq('region_id',REGIONS[regionSel]?.id);return q}
async function fetchRecordById(id){
  let q=sb.from('records').select('*').eq('id',id);q=scopedRecordsQuery(q);const {data:r,error}=await q.maybeSingle();if(error)throw error;if(!r)return null;
  const {data:media,error:mErr}=await sb.from('media').select('id,record_id,storage_path,file_name,mime_type,file_size,uploaded_by,created_at').eq('record_id',id).order('created_at');if(mErr)throw mErr;
  const attachments=(media||[]).map(m=>({id:m.id,recordId:m.record_id,storagePath:m.storage_path,name:m.file_name,type:m.mime_type||'application/octet-stream',size:Number(m.file_size||0),createdAt:m.created_at,isRemote:true}));
  const item=fromDbRecord(r,attachments);recordCache=[item,...recordCache.filter(x=>x.id!==id)];return item;
}
async function fetchRecords(){const rows=await fetchAllPaged(()=>{let q=sb.from('records').select('*').order('record_date',{ascending:false}).order('created_at',{ascending:false});return scopedRecordsQuery(q)});recordCache=rows.map(r=>fromDbRecord(r,[]));return recordCache}
function safeFilterText(v){return String(v||'').trim().replace(/[(),]/g,' ').replace(/[%_]/g,' ')}
function buildRecordQuery(filters={},withCount=false){
  let q=withCount?sb.from('records').select('*',{count:'exact'}):sb.from('records').select('*');q=scopedRecordsQuery(q);
  if(filters.kind)q=q.eq('kind',dbKind(filters.kind));
  if(filters.person)q=q.ilike('employee_name',`%${safeFilterText(filters.person)}%`);
  if(filters.manager)q=q.eq('manager_name_snapshot',filters.manager);
  if(filters.from)q=q.gte('record_date',filters.from);if(filters.to)q=q.lte('record_date',filters.to);
  const needle=safeFilterText(filters.q);if(needle){const pat=`%${needle}%`;q=q.or(`store_name_snapshot.ilike.${pat},manager_name_snapshot.ilike.${pat},violation_type_snapshot.ilike.${pat},employee_name.ilike.${pat},story.ilike.${pat},created_by_name_snapshot.ilike.${pat}`)}
  return q.order('record_date',{ascending:false}).order('created_at',{ascending:false});
}
async function fetchRecordPage(filters,page=0,pageSize=100){const start=page*pageSize;const {data,error,count}=await buildRecordQuery(filters,true).range(start,start+pageSize-1);if(error)throw error;const rows=(data||[]).map(r=>fromDbRecord(r,[]));recordCache=rows;return {rows,count:Number(count||0)}}
async function fetchFilteredRecords(filters){const rows=await fetchAllPaged(()=>buildRecordQuery(filters,false),1000,50000);return rows.map(r=>fromDbRecord(r,[]))}
async function dashboardCount(kind,date){let q=sb.from('records').select('id',{count:'exact',head:true}).eq('kind',kind).eq('record_date',date);q=scopedRecordsQuery(q);const {count,error}=await q;if(error)throw error;return Number(count||0)}
async function dashboardLatest(kind,limit=7){let q=sb.from('records').select('*').eq('kind',kind).order('record_date',{ascending:false}).order('created_at',{ascending:false}).limit(limit);q=scopedRecordsQuery(q);const {data,error}=await q;if(error)throw error;return (data||[]).map(r=>fromDbRecord(r,[]))}
function fromDbRecord(r,attachments=[]){const e=r.evaluation_data||{};const kind=uiKind(r.kind);return {id:r.id,kind,region:regionCodeFromUuid(r.region_id),regionId:r.region_id,date:r.record_date,storeId:r.store_id,store:r.store_name_snapshot||r.store_number_snapshot||'',managerId:r.manager_id,manager:r.manager_name_snapshot||'',violationTypeId:r.violation_type_id,violationType:r.violation_type_snapshot||'',employee:kind==='eval'?'':(r.employee_name||''),seller:kind==='eval'?(r.employee_name||''):'',story:r.story||'',damageCustomer:formatMoneyValue(r.damage_customer),damageStore:formatMoneyValue(r.damage_store),repaidCustomer:formatMoneyValue(r.reimbursed_customer),repaidStore:formatMoneyValue(r.reimbursed_store),startTime:e.start_time||'',buyerGender:e.buyer_gender||'ж',scores:Array.isArray(e.scores)?e.scores.map(Number):[0,0,0,0,0],comment:e.comment||'',attachments,createdAt:r.created_at,createdBy:r.created_by,createdByName:r.created_by_name_snapshot||'',updatedAt:r.updated_at,updatedBy:r.updated_by};}
function toDbRecord(r){const kind=dbKind(r.kind),typeList=typesFor(r.kind,r.region),vt=typeList.find(x=>x.name===r.violationType);return {region_id:REGIONS[r.region]?.id,kind,record_date:r.date,store_id:r.storeId||null,store_number_snapshot:r.storeNumber||((r.store||'').match(/^\d+/)?.[0]||null),store_name_snapshot:r.store||null,manager_id:r.managerId||null,manager_name_snapshot:r.manager||null,employee_name:r.kind==='eval'?(r.seller||null):(r.employee||null),violation_type_id:vt?.id||r.violationTypeId||null,violation_type_snapshot:r.kind==='eval'?null:(r.violationType||null),story:r.kind==='eval'?null:(r.story||null),damage_customer:moneyNumber(r.damageCustomer),damage_store:r.kind==='cat1'?moneyNumber(r.damageStore):0,reimbursed_customer:moneyNumber(r.repaidCustomer),reimbursed_store:r.kind==='cat1'?moneyNumber(r.repaidStore):0,evaluation_data:r.kind==='eval'?{start_time:r.startTime,buyer_gender:r.buyerGender,scores:r.scores.map(Number),total:r.scores.reduce((a,b)=>a+Number(b||0),0),comment:r.comment||''}:null,updated_by:currentUser.id};}
async function saveRecord(r,isEdit){const payload=toDbRecord(r);if(isEdit){const {data,error}=await sb.from('records').update(payload).eq('id',r.id).select('*').single();if(error)throw error;return data}else{payload.created_by=currentUser.id;payload.created_by_name_snapshot=currentUser.name;delete payload.updated_by;const {data,error}=await sb.from('records').insert(payload).select('*').single();if(error)throw error;return data}}
async function deleteRecordServer(id){const {error}=await sb.from('records').delete().eq('id',id);if(error)throw error}

async function getStores(regionCode=selectedRegionCode(),includeInactive=false){const rg=REGIONS[regionCode];if(!rg)return[];let q=sb.from('stores').select('id,region_id,store_number,display_name,manager_id,is_active,closed_at,created_at,updated_at,managers(id,full_name)').eq('region_id',rg.id).order('store_number');if(!includeInactive)q=q.eq('is_active',true);const {data,error}=await q;if(error)throw error;storeCache=(data||[]).map(s=>({id:s.id,region:regionCode,regionId:s.region_id,number:s.store_number,name:s.display_name,managerId:s.manager_id,manager:s.managers?.full_name||'',active:s.is_active,closedAt:s.closed_at,createdAt:s.created_at,updatedAt:s.updated_at}));return storeCache}
