function openTypePicker(regionOverride=null){if(!canCreate()){toast('У этой роли только просмотр',true);return}const region=regionOverride||creationRegionCode();if(!region){openRegionPicker();return}$('#recordDialogBody').innerHTML=`<div class="dialog-card"><div class="dialog-head"><div><h3>Что добавить?</h3><p class="muted">${esc(REGIONS[region]?.name||region)}</p></div><button class="close-x">×</button></div><div class="quick-grid"><div class="quick-card" data-k="cat1"><div class="quick-icon">⚠</div><div class="quick-title">Категория 1</div></div><div class="quick-card" data-k="cat2"><div class="quick-icon">◈</div><div class="quick-title">Категория 2</div></div><div class="quick-card" data-k="eval"><div class="quick-icon">★</div><div class="quick-title">Оценка</div></div></div></div>`;const d=$('#recordDialog');d.showModal();$('#recordDialogBody .close-x').onclick=()=>d.close();$$('#recordDialogBody [data-k]').forEach(x=>x.onclick=()=>{d.close();openRecordForm(x.dataset.k,null,region)})}

function parseMoneyMatch(text,patterns){for(const p of patterns){const m=text.match(p);if(m)return formatMoneyValue(m[1])}return ''}
function extractEmployeeFromStory(text){const patterns=[/(?:ПІБ|П\.І\.Б\.?|ФИО|Ф\.И\.О\.?)\s*[:\-]?\s*([А-ЯІЇЄҐA-Z][А-Яа-яІіЇїЄєҐґ'’\-]+\s+[А-ЯІЇЄҐA-Z][А-Яа-яІіЇїЄєҐґ'’\-]+(?:\s+[А-ЯІЇЄҐA-Z][А-Яа-яІіЇїЄєҐґ'’\-]+)?)/i,/\b([А-ЯІЇЄҐ][А-Яа-яІіЇїЄєҐґ'’\-]+\s+[А-ЯІЇЄҐ][А-Яа-яІіЇїЄєҐґ'’\-]+\s+[А-ЯІЇЄҐ][А-Яа-яІіЇїЄєҐґ'’\-]+)\b/];for(const p of patterns){const m=text.match(p);if(m)return m[1].trim()}return ''}
function analyzeStory(text){return {employee:extractEmployeeFromStory(text),damageCustomer:parseMoneyMatch(text,[/(?:шкода|ущерб|збиток)\s+(?:покупц\w*|покупател\w*)[^\d]{0,30}(\d+(?:[.,]\d{1,2})?)/i,/(?:на суму|на сумму)\s+(\d+(?:[.,]\d{1,2})?)/i]),damageStore:parseMoneyMatch(text,[/(?:шкода|ущерб|збиток)\s+(?:магазин\w*)[^\d]{0,30}(\d+(?:[.,]\d{1,2})?)/i]),repaidCustomer:parseMoneyMatch(text,[/(?:відшкод\w*|возмещ\w*|повернен\w*)\s+(?:покупц\w*|покупател\w*)[^\d]{0,30}(\d+(?:[.,]\d{1,2})?)/i]),repaidStore:parseMoneyMatch(text,[/(?:відшкод\w*|возмещ\w*)\s+(?:магазин\w*)[^\d]{0,30}(\d+(?:[.,]\d{1,2})?)/i])}}
function fillFromStory(form,kind,force=false){const story=form.elements.story?.value||'';if(!story.trim())return;const a=analyzeStory(story),filled=[];const set=(name,val,label)=>{const el=form.elements[name];if(!el||!val)return;if(force||!el.dataset.userTouched||!el.value||el.value==='0,00'){el.value=el.classList.contains('money-entry')?formatMoneyValue(val):val;filled.push(label)}};set('employee',a.employee,'Ф.И.О.');set('damageCustomer',a.damageCustomer,'ущерб покупателю');if(kind==='cat1')set('damageStore',a.damageStore,'ущерб магазину');set('repaidCustomer',a.repaidCustomer,'возмещение покупателю');if(kind==='cat1')set('repaidStore',a.repaidStore,'возмещение магазину');const s=$('#storyAutoStatus',form);if(s)s.textContent=filled.length?`Распознано: ${filled.join(', ')}`:'Автозаполнение ничего не нашло — можно заполнить вручную.'}

function clearMediaUrls(){for(const u of mediaPreviewUrls)try{URL.revokeObjectURL(u)}catch{}mediaPreviewUrls=[]}
async function mediaAccess(body){const {data,error}=await sb.functions.invoke('media-access',{body});if(error)throw error;if(data?.error)throw new Error(data.error);return data}
async function getMediaUrl(att){if(att.previewUrl)return att.previewUrl;if(att.blob){const u=URL.createObjectURL(att.blob);mediaPreviewUrls.push(u);return u}if(att.id){const d=await mediaAccess({action:'view',mediaId:att.id});att.previewUrl=d.url;return d.url}return ''}
function putWithProgress(url,file,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('PUT',url,true);if(file.type)xhr.setRequestHeader('Content-Type',file.type);xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress?.(Math.round(e.loaded/e.total*100))};xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve():reject(new Error(`Backblaze: HTTP ${xhr.status}`));xhr.onerror=()=>reject(new Error('Не удалось загрузить файл в Backblaze. Проверь CORS бакета.'));xhr.send(file)})}
async function uploadOneMedia(recordId,item,onProgress){const signed=await mediaAccess({action:'upload',recordId,fileName:item.name,contentType:item.type||'application/octet-stream',fileSize:item.size});await putWithProgress(signed.url,item.blob,onProgress);const {data,error}=await sb.from('media').insert({record_id:recordId,storage_path:signed.storagePath,file_name:item.name,mime_type:item.type||null,file_size:item.size,uploaded_by:currentUser.id}).select('id,record_id,storage_path,file_name,mime_type,file_size,created_at').single();if(error)throw error;return {id:data.id,recordId:data.record_id,storagePath:data.storage_path,name:data.file_name,type:data.mime_type||'application/octet-stream',size:Number(data.file_size||0),createdAt:data.created_at,isRemote:true}}
async function deleteOneMedia(att){if(!att?.id)return;await mediaAccess({action:'delete',mediaId:att.id});const {error}=await sb.from('media').delete().eq('id',att.id);if(error)throw error}
async function openFullscreenImage(att){if(!att)return;const d=$('#mediaDialog'),body=$('#mediaDialogBody');if(d.open)d.close();let url='';try{url=await getMediaUrl(att)}catch(e){toast('Не удалось открыть файл: '+e.message,true);return}if(!url)return;const isImage=String(att.type||'').startsWith('image/');body.innerHTML=`<div class="media-modal-shell"><button class="lightbox-close" type="button">×</button>${isImage?`<img class="media-modal-image" src="${esc(url)}" alt="${esc(att.name)}">`:`<video class="media-modal-image" src="${esc(url)}" controls autoplay></video>`}<div class="lightbox-caption">${esc(att.name)}</div></div>`;const close=()=>{if(d.open)d.close()};body.querySelector('.lightbox-close').onclick=close;d.onclick=e=>{if(e.target===d)close()};d.oncancel=e=>{e.preventDefault();close()};document.body.classList.add('media-view-open');d.addEventListener('close',()=>{document.body.classList.remove('media-view-open');body.innerHTML=''}, {once:true});d.showModal()}
async function openRecordForm(kind,existing=null,regionOverride=null){
  const isEdit=!!existing,region=existing?.region||regionOverride||creationRegionCode();if(!region&&!isEdit){openRegionPicker(kind);return}if(!hasRegionAccess(region)){toast('Нет доступа к этому региону',true);return}
  const r=existing||{},opts=await storeOptions(region,r.store||''),managerLocked=['operator','senior'].includes(currentUser.role),managerAttrs=managerLocked?' readonly tabindex="-1" title="Менеджер подставляется автоматически"':'';
  let working=[...(r.attachments||[])],pending=[],deleted=[];
  let fields='';
  if(kind==='cat1'||kind==='cat2'){
    const types=typesFor(kind,region);
    fields=`<div class="form-grid"><label>Дата проверки<input name="date" type="date" value="${esc(r.date||todayKyiv())}" required></label><label>Магазин<select name="storeSelect" required>${opts}</select><input name="customStore" class="hidden" placeholder="Например: 999 Харьков"></label><label>Менеджер<input name="manager" value="${esc(r.manager||'')}" placeholder="Подставится по магазину"${managerAttrs}></label><label>Тип нарушения<select name="violationType" required>${typeOptions(types,r.violationType)}</select></label><label class="full">Ф.И.О. сотрудника<input name="employee" value="${esc(r.employee||'')}" placeholder="Вставится из фабулы автоматически"></label><label class="full">Фабула<textarea name="story" required placeholder="Вставь или напиши фабулу...">${esc(r.story||'')}</textarea><div class="story-tools"><button type="button" class="btn ghost small-btn" id="parseStoryBtn">Распознать фабулу</button><span id="storyAutoStatus" class="file-hint">При вставке попробуем определить Ф.И.О. и суммы.</span></div></label><div class="form-section"><div class="form-section-title">${kind==='cat1'?'Ущерб и возмещение':'Ущерб'}</div><div class="money-grid">${kind==='cat1'?`${moneyField('damageCustomer','Ущерб покупателю',r.damageCustomer)}${moneyField('damageStore','Ущерб магазину',r.damageStore)}${moneyField('repaidCustomer','Возмещено покупателю',r.repaidCustomer)}${moneyField('repaidStore','Возмещено магазину',r.repaidStore)}`:`${moneyField('damageCustomer','Ущерб покупателю',r.damageCustomer)}${moneyField('repaidCustomer','Возмещено покупателю',r.repaidCustomer)}`}</div></div></div>`;
  }else{
    fields=`<div class="form-grid"><label>Дата оценки<input name="date" type="date" value="${esc(r.date||todayKyiv())}" required></label><label>Время начала<input name="startTime" type="time" value="${esc(r.startTime||'')}" required></label><label>Магазин<select name="storeSelect" required>${opts}</select><input name="customStore" class="hidden" placeholder="Другой магазин"></label><label>Менеджер<input name="manager" value="${esc(r.manager||'')}"${managerAttrs}></label><label class="full">Продавец<input name="seller" value="${esc(r.seller||'')}" required></label><label>Пол покупателя<select name="buyerGender"><option value="ж" ${r.buyerGender==='ж'?'selected':''}>Женщина</option><option value="м" ${r.buyerGender==='м'?'selected':''}>Мужчина</option></select></label><div></div><div class="form-section"><div class="form-section-title">Критерии оценки</div>${CRITERIA.map((c,i)=>`<div class="score-grid"><span>${c}</span><select name="score${i}" class="score-sel"><option value="0" ${Number(r.scores?.[i]||0)===0?'selected':''}>0</option><option value="2" ${Number(r.scores?.[i])===2?'selected':''}>2</option></select></div>`).join('')}<div class="score-total"><span>Общая сумма баллов</span><strong id="scoreTotal">${(r.scores||[0,0,0,0,0]).reduce((a,b)=>a+Number(b),0)}</strong></div></div><label class="full">Комментарий видеооператора<textarea name="comment">${esc(r.comment||'')}</textarea></label></div>`;
  }
  $('#recordDialogBody').innerHTML=`<form id="recordForm" class="dialog-card"><div class="dialog-head"><div><h3>${isEdit?'Редактирование':kind==='cat1'?'Категория 1':kind==='cat2'?'Категория 2':'Оценка'}</h3><p class="muted">${isEdit?recordDisplayId(r):`Новая запись · ${esc(REGIONS[region]?.name||region)}`}</p></div><button type="button" class="close-x">×</button></div>${isEdit?'<div class="notice">Изменения записи фиксируются в серверном журнале. Медиа хранится в закрытом Backblaze B2.</div>':''}${fields}<div class="form-section"><div class="form-section-title">Фото и видео</div><div id="existingMedia"></div><div id="newMedia"></div><div class="upload-box"><input name="attachments" type="file" accept="image/*,video/*" multiple><div class="file-hint">Файлы будут загружены напрямую в Backblaze после сохранения записи.</div></div></div><div id="saveStatus" class="server-note"></div><div class="dialog-actions">${isEdit&&canDelete()?'<button type="button" class="btn danger delete-record-edit">Удалить нарушение</button>':''}<button type="button" class="btn ghost cancel">Отмена</button><button class="btn primary" id="recordSubmit" type="submit">${isEdit?'Сохранить изменения':'Сохранить запись'}</button></div></form>`;
  const d=$('#recordDialog'),f=$('#recordForm');d.showModal();$('.close-x',f).onclick=()=>d.close();$('.cancel',f).onclick=()=>d.close();$('.delete-record-edit',f)?.addEventListener('click',()=>confirmDelete(r.id,d));bindMoneyFields(f);$$('input,textarea',f).forEach(el=>{if(el.name&&el.name!=='story')el.addEventListener('input',()=>el.dataset.userTouched='1')});

  const renderExisting=async()=>{
    const box=$('#existingMedia');if(!working.length){box.innerHTML='';return}
    box.innerHTML=`<div class="file-hint media-label">Уже сохранённые материалы</div><div class="media-edit-grid">${working.map((a,i)=>`<div class="media-edit-card" data-media-card="${i}"><div class="media-preview"><button type="button" class="media-open-btn open-existing" data-index="${i}"><div class="remote-media-placeholder">${String(a.type).startsWith('image/')?'Загрузка превью…':'▶ Видео'}</div></button></div><div class="media-edit-meta"><span title="${esc(a.name)}">${esc(a.name)}</span><div class="media-edit-actions"><button type="button" class="btn ghost tiny-btn replace-media" data-index="${i}">Заменить</button><button type="button" class="btn danger tiny-btn remove-media" data-index="${i}">Удалить</button></div></div></div>`).join('')}</div>`;
    $$('.remove-media',box).forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.index);const old=working[idx];if(old?.id)deleted.push(old);working.splice(idx,1);renderExisting()});
    $$('.replace-media',box).forEach(b=>b.onclick=()=>{const idx=Number(b.dataset.index);const inp=document.createElement('input');inp.type='file';inp.accept='image/*,video/*';inp.onchange=()=>{const file=inp.files?.[0];if(!file)return;const old=working[idx];if(old?.id)deleted.push(old);working.splice(idx,1);pending.push({name:file.name,type:file.type,size:file.size,blob:file,progress:0});renderExisting();renderPending()};inp.click()});
    $$('.open-existing',box).forEach(b=>b.onclick=()=>openFullscreenImage(working[Number(b.dataset.index)]));
    working.forEach(async(a,i)=>{if(!String(a.type).startsWith('image/'))return;try{const u=await getMediaUrl(a);const ph=$(`[data-media-card="${i}"] .remote-media-placeholder`,box);if(ph)ph.outerHTML=`<img src="${esc(u)}" alt="">`}catch{}});
  };
  const renderPending=()=>{const box=$('#newMedia');if(!pending.length){box.innerHTML='';return}box.innerHTML=`<div class="file-hint media-label">Новые материалы</div><div class="media-edit-grid">${pending.map((a,i)=>{let preview='';if(a.blob&&String(a.type).startsWith('image/')){const u=URL.createObjectURL(a.blob);mediaPreviewUrls.push(u);preview=`<img src="${u}" alt="" data-pending-index="${i}">`}else preview='<div class="remote-media-placeholder">▶ Видео</div>';return `<div class="media-edit-card pending-card"><div class="media-preview">${preview}</div><div class="media-edit-meta"><span>${esc(a.name)}</span><div class="upload-progress"><i style="width:${a.progress||0}%"></i></div><div class="upload-status">${a.progress?`Загрузка ${a.progress}%`:'Готово к загрузке'}</div><button type="button" class="btn danger tiny-btn remove-pending" data-index="${i}">Убрать</button></div></div>`}).join('')}</div>`;$$('.remove-pending',box).forEach(b=>b.onclick=()=>{pending.splice(Number(b.dataset.index),1);renderPending()});$$('img[data-pending-index]',box).forEach(img=>img.onclick=()=>openFullscreenImage(pending[Number(img.dataset.pendingIndex)]))};
  await renderExisting();renderPending();
  f.elements.attachments.onchange=()=>{for(const file of [...f.elements.attachments.files])pending.push({name:file.name,type:file.type,size:file.size,blob:file,progress:0});f.elements.attachments.value='';renderPending()};

  const ss=f.elements.storeSelect,cs=f.elements.customStore,mg=f.elements.manager;let first=true,selectedStoreObj=r.storeId?{id:r.storeId,managerId:r.managerId,number:(r.store||'').match(/^\d+/)?.[0]}:null;
  const updStore=async()=>{const v=ss.value,isCustom=v==='__custom';cs.classList.toggle('hidden',!isCustom);if(isCustom){selectedStoreObj=null;if(!isEdit||!first)mg.value='';first=false;return}const st=await findStore(region,v);selectedStoreObj=st;if(st&&(!first||!isEdit))mg.value=st.manager||'';first=false};ss.onchange=updStore;await updStore();
  if(kind==='eval')$$('.score-sel',f).forEach(s=>s.onchange=()=>$('#scoreTotal').textContent=$$('.score-sel',f).reduce((a,x)=>a+Number(x.value),0));
  if(kind==='cat1'||kind==='cat2'){const story=f.elements.story;let timer;const auto=()=>{clearTimeout(timer);timer=setTimeout(()=>fillFromStory(f,kind,false),180)};story.addEventListener('paste',()=>setTimeout(auto,20));story.addEventListener('input',auto);$('#parseStoryBtn',f).onclick=()=>fillFromStory(f,kind,true)}

  f.onsubmit=async e=>{
    e.preventDefault();const btn=$('#recordSubmit',f),status=$('#saveStatus',f),fd=new FormData(f),storeVal=fd.get('storeSelect')==='__custom'?fd.get('customStore').trim():fd.get('storeSelect');if(!storeVal){toast('Укажи магазин',true);return}
    setBusy(btn,true,'Сохраняем…');status.textContent='Сохраняем запись на сервере…';
    try{
      if(fd.get('storeSelect')!=='__custom')selectedStoreObj=await findStore(region,storeVal);
      const base={id:r.id||null,kind,region,date:fd.get('date'),store:storeVal,storeId:selectedStoreObj?.id||r.storeId||null,storeNumber:selectedStoreObj?.number||((storeVal||'').match(/^\d+/)?.[0]||null),manager:fd.get('manager').trim(),managerId:selectedStoreObj?.managerId||r.managerId||null,createdAt:r.createdAt||nowISO(),createdBy:r.createdBy||currentUser.id,createdByName:r.createdByName||currentUser.name};
      const nr=(kind==='cat1'||kind==='cat2')?{...base,violationType:fd.get('violationType'),employee:fd.get('employee').trim(),story:fd.get('story').trim(),damageCustomer:formatMoneyValue(fd.get('damageCustomer')),repaidCustomer:formatMoneyValue(fd.get('repaidCustomer')),...(kind==='cat1'?{damageStore:formatMoneyValue(fd.get('damageStore')),repaidStore:formatMoneyValue(fd.get('repaidStore'))}:{})}:{...base,startTime:fd.get('startTime'),seller:fd.get('seller').trim(),buyerGender:fd.get('buyerGender'),scores:CRITERIA.map((_,i)=>Number(fd.get('score'+i)||0)),comment:fd.get('comment').trim()};
      const saved=await saveRecord(nr,isEdit),recordId=saved.id;
      if(deleted.length){status.textContent='Удаляем старые материалы…';for(const a of deleted)await deleteOneMedia(a)}
      if(pending.length){for(let i=0;i<pending.length;i++){status.textContent=`Загрузка файла ${i+1} из ${pending.length}: ${pending[i].name}`;await uploadOneMedia(recordId,pending[i],p=>{pending[i].progress=p;renderPending()})}}
      d.close();clearMediaUrls();toast(isEdit?'Изменения сохранены на сервере':'Запись сохранена на сервере');await renderPage();
    }catch(err){console.error(err);status.textContent='Ошибка: '+(err.message||'не удалось сохранить');toast(err.message||'Ошибка сохранения',true)}finally{setBusy(btn,false)}
  };
  d.addEventListener('close',clearMediaUrls,{once:true});
}

async function editRecord(id){if(!canEdit()){toast('Нет прав на редактирование',true);return}const r=await fetchRecordById(id);if(r)openRecordForm(r.kind,r);else toast('Эта запись больше не существует',true)}
async function viewRecord(id){const r=await fetchRecordById(id);if(!r){toast('Эта запись больше не существует',true);return}const att=(r.attachments||[]).map((a,i)=>`<div class="media-card"><button class="media-open-btn open-media" data-index="${i}">${String(a.type).startsWith('image/')?'<div class="remote-media-placeholder">Нажмите, чтобы открыть фото</div>':'<div class="media-file-icon">▶</div>'}</button><div class="media-name">${esc(a.name)}</div></div>`).join('');const body=r.kind==='eval'?`<div class="detail-grid"><div class="detail"><div class="k">Продавец</div><div class="v">${esc(r.seller)}</div></div><div class="detail"><div class="k">Время</div><div class="v">${esc(r.startTime)}</div></div><div class="detail"><div class="k">Пол покупателя</div><div class="v">${esc(r.buyerGender)}</div></div></div><div class="divider"></div>${CRITERIA.map((c,i)=>`<div class="audit-line"><span>${c}</span><b>${r.scores?.[i]??0}</b></div>`).join('')}<div class="score-total" style="margin-top:12px"><span>Итого</span><strong>${(r.scores||[]).reduce((a,b)=>a+Number(b),0)} / 10</strong></div><div class="divider"></div><h3 style="font-size:14px;margin-bottom:9px">Комментарий</h3><div class="story">${esc(r.comment||'—')}</div>`:`<div class="detail-grid"><div class="detail"><div class="k">Сотрудник</div><div class="v">${esc(r.employee||'—')}</div></div><div class="detail"><div class="k">Тип нарушения</div><div class="v">${esc(r.violationType||'—')}</div></div><div class="detail"><div class="k">Автор</div><div class="v">${esc(r.createdByName)}</div></div></div><div class="divider"></div><h3 style="font-size:14px;margin-bottom:9px">Фабула</h3><div class="story">${esc(r.story||'—')}</div><div class="divider"></div><div class="detail-grid"><div class="detail"><div class="k">Ущерб покупателю</div><div class="v">${money(r.damageCustomer)}</div></div>${r.kind==='cat1'?`<div class="detail"><div class="k">Ущерб магазину</div><div class="v">${money(r.damageStore)}</div></div>`:''}<div class="detail"><div class="k">Возмещено покупателю</div><div class="v">${money(r.repaidCustomer)}</div></div>${r.kind==='cat1'?`<div class="detail"><div class="k">Возмещено магазину</div><div class="v">${money(r.repaidStore)}</div></div>`:''}</div>`;$('#viewDialogBody').innerHTML=`<div class="dialog-card"><div class="dialog-head"><div><div>${typeBadge(r.kind)}</div><h3 style="margin-top:8px">${esc(recordDisplayId(r))}</h3><p class="muted">${fmtDate(r.date)} · ${esc(r.store)} · ${esc(r.manager||'менеджер не указан')}</p></div><button class="close-x">×</button></div>${body}<div class="divider"></div><h3 style="font-size:14px;margin-bottom:10px">Фото и видео (${r.attachments?.length||0})</h3>${att?`<div class="media-grid">${att}</div>`:'<div class="muted small">Материалы не прикреплены.</div>'}<div class="dialog-actions">${canDelete()?'<button class="btn danger delete-record">Удалить</button>':''}${canEdit()?'<button class="btn ghost edit-record">Редактировать</button>':''}<button class="btn primary close-bottom">Закрыть</button></div></div>`;const d=$('#viewDialog');d.showModal();$$('#viewDialogBody .close-x,#viewDialogBody .close-bottom').forEach(b=>b.onclick=()=>d.close());$$('.open-media',$('#viewDialogBody')).forEach(b=>b.onclick=()=>openFullscreenImage((r.attachments||[])[Number(b.dataset.index)]));$('#viewDialogBody .edit-record')?.addEventListener('click',()=>{d.close();editRecord(id)});$('#viewDialogBody .delete-record')?.addEventListener('click',()=>confirmDelete(id,d))}
function confirmDelete(id,parent){$('#confirmText').textContent='Нарушение будет удалено полностью вместе со всеми привязанными фото и видео. Отменить это действие нельзя. Удаление зафиксируется в истории.';const c=$('#confirmDialog');c.showModal();c.onclose=async()=>{if(c.returnValue!=='ok')return;try{const r=await fetchRecordById(id);for(const a of r?.attachments||[]){try{await mediaAccess({action:'delete',mediaId:a.id})}catch(e){throw new Error(`Не удалось удалить файл «${a.name||'медиа'}»: ${e.message||e}`)}}await deleteRecordServer(id);recordCache=recordCache.filter(x=>x.id!==id);parent.close();toast('Нарушение полностью удалено');await renderPage()}catch(e){toast('Не удалось удалить полностью: '+e.message,true)}}}
function fieldLabel(k){return {record_date:'Дата',store_name_snapshot:'Магазин',store_number_snapshot:'Номер ТТ',manager_name_snapshot:'Менеджер',violation_type_snapshot:'Тип нарушения',employee_name:'Сотрудник / продавец',story:'Фабула',damage_customer:'Ущерб покупателю',damage_store:'Ущерб магазину',reimbursed_customer:'Возмещено покупателю',reimbursed_store:'Возмещено магазину',evaluation_data:'Оценка',kind:'Тип записи',updated_by:'Кем изменено',store_id:'Магазин',manager_id:'Менеджер',violation_type_id:'Тип нарушения'}[k]||k}
function shortVal(v){if(v===null||v===undefined)return '—';if(typeof v==='object')return JSON.stringify(v);return String(v)}
function renderAuditChanges(a){const ch=a.changes||{};if(a.action==='update'){const parts=[];for(const [k,v] of Object.entries(ch)){if(['updated_at','updated_by'].includes(k))continue;if(k==='evaluation_data'&&v?.before&&v?.after){const before=v.before||{},after=v.after||{};if(before.start_time!==after.start_time)parts.push(['Время',before.start_time,after.start_time]);if(before.buyer_gender!==after.buyer_gender)parts.push(['Пол покупателя',before.buyer_gender,after.buyer_gender]);const bs=before.scores||[],as=after.scores||[];CRITERIA.forEach((c,i)=>{if(Number(bs[i]||0)!==Number(as[i]||0))parts.push([c,Number(bs[i]||0),Number(as[i]||0)])});if((before.comment||'')!==(after.comment||''))parts.push(['Комментарий',before.comment,after.comment]);continue}parts.push([fieldLabel(k),v?.before,v?.after])}return parts.map(x=>`<div class="audit-change"><b>${esc(x[0])}</b><div class="audit-values"><span class="before">Было: ${esc(shortVal(x[1]))}</span><span class="after">Стало: ${esc(shortVal(x[2]))}</span></div></div>`).join('')||'<div class="muted small">Служебное обновление</div>'}
  const labels={create:'Запись создана',delete:'Запись удалена',media_add:'Добавлен файл',media_delete:'Удалён файл'};return `<div class="audit-change"><b>${esc(labels[a.action]||a.action)}</b><div class="muted small">${esc(Object.entries(ch).map(([k,v])=>`${fieldLabel(k)}: ${shortVal(v)}`).join(' · '))}</div></div>`}
async function renderAudit(){if(!['owner','boss'].includes(currentUser.role)){go('dashboard');return}let q=sb.from('audit_log').select('*').order('created_at',{ascending:false}).limit(2000);const reg=$('#regionSelect').value;if(reg!=='all')q=q.eq('region_id',REGIONS[reg]?.id);const {data,error}=await q;if(error)throw error;const a=data||[];$('#content').innerHTML=`<div class="panel" style="margin-top:0"><div class="panel-head"><div><h3>Журнал изменений</h3><div class="muted small">Серверная история действий с записями.</div></div><span class="muted small">${a.length} событий</span></div>${a.length?a.map(x=>`<div class="audit-item ${x.record_id?'audit-clickable':''}" ${x.record_id?`data-record-id="${esc(x.record_id)}"`:''}><div class="audit-line"><b>${esc(x.action==='create'?'Создание':x.action==='update'?'Изменение':x.action==='delete'?'Удаление':x.action)}</b><span class="muted small">${fmtDateTime(x.created_at)}</span></div><div class="muted small">${esc(x.actor_name||'Система')}</div>${renderAuditChanges(x)}${x.record_id?'<div class="audit-open-hint">Открыть запись →</div>':''}</div>`).join(''):'<div class="empty"><b>История пока пустая</b>Изменения появятся здесь автоматически.</div>'}</div>`;$$('.audit-clickable').forEach(x=>x.onclick=()=>viewRecord(x.dataset.recordId))}

function usageCard(title,used,limit,caution=70,warning=80,critical=90){const pct=limit?Math.min(100,used/limit*100):0,cls=pct>=critical?'critical':pct>=warning?'warn':'';return `<div class="usage-card ${cls}"><div class="usage-head"><b>${esc(title)}</b><strong>${pct.toFixed(1)}%</strong></div><div class="usage-bar"><i style="width:${pct}%"></i></div><div class="usage-meta">${humanBytes(used)} / ${humanBytes(limit)}${pct>=critical?' · Критический уровень':pct>=warning?' · Скоро лимит':pct>=caution?' · Стоит следить':''}</div></div>`}
async function renderSettings(){
  if(currentUser.role!=='owner'){go('dashboard');return}
  const regCode=selectedRegionCode(),reg=REGIONS[regCode]||Object.values(REGIONS)[0];
  const [{data:profiles,error:pErr},{data:userRegionRows,error:urErr},stores,{data:usage,error:uErr}]=await Promise.all([sb.from('profiles').select('id,username,full_name,role,region_id,is_active,created_at').order('full_name'),sb.from('user_regions').select('user_id,region_id'),getStores(reg.code,true),sb.rpc('owner_usage_stats')]);if(pErr)throw pErr;if(urErr)throw urErr;if(uErr)console.warn(uErr);profileCache=(profiles||[]).map(u=>({...u,region_ids:(userRegionRows||[]).filter(x=>x.user_id===u.id).map(x=>x.region_id)}));const active=stores.filter(s=>s.active).length;
  const usageData=usage||{};
  $('#content').innerHTML=`<div class="notice"><b>Серверная версия активна.</b> Аккаунты и записи — Supabase. Фото и видео — закрытый Backblaze B2.</div><div class="panel" style="margin-top:0"><div class="panel-head"><div><h3>Использование системы</h3><div class="muted small">Предупреждения заложены на 70%, 80% и 90%.</div></div><span class="badge eval">BACKBLAZE B2</span></div><div class="usage-grid">${usageCard('База данных',Number(usageData.databaseBytes||0),Number(usageData.databaseLimitBytes||524288000),Number(usageData.cautionPercent||70),Number(usageData.warningPercent||80),Number(usageData.criticalPercent||90))}${usageCard('Фото и видео',Number(usageData.mediaBytes||0),Number(usageData.mediaLimitBytes||10737418240),Number(usageData.cautionPercent||70),Number(usageData.warningPercent||80),Number(usageData.criticalPercent||90))}</div><div class="server-note">Медиа считается по файлам, зарегистрированным в PRIZ Control. Файлов: ${Number(usageData.mediaCount||0)}.</div></div><div class="settings-grid"><div class="settings-card"><h4>Регионы</h4>${Object.values(REGIONS).map(r=>`<div class="user-row"><div><b>${esc(r.name)}</b><span>Код: ${esc(r.code)}</span></div><span class="badge eval">АКТИВЕН</span></div>`).join('')}</div><div class="settings-card"><div class="panel-head compact-head"><h4>Пользователи и роли</h4><button class="btn primary small-btn" id="addUserBtn">+ Аккаунт</button></div><div class="users-list">${profileCache.map(u=>{const ids=['owner','boss'].includes(u.role)?[]:(u.region_ids?.length?u.region_ids:(u.region_id?[u.region_id]:[]));const rr=['owner','boss'].includes(u.role)?'Все регионы':ids.map(id=>REGION_BY_UUID[id]?.name||'—').join(', ');return `<div class="user-row"><div><b>${esc(u.full_name)}</b><span>${esc(u.username)} · ${esc(rr||'—')}</span><div class="user-status ${u.is_active?'on':'off'}">${u.is_active?'АКТИВЕН':'ОТКЛЮЧЁН'}</div></div><div class="user-actions"><div class="role-pill">${ROLE_LABEL[u.role]}</div><button class="btn ghost tiny-btn edit-user" data-id="${esc(u.id)}">Изменить</button></div></div>`}).join('')}</div></div></div><div class="panel"><div class="panel-head"><div><h3>Магазины и менеджеры · ${esc(reg.name)}</h3><div class="muted small">Активных: ${active} · Закрытых: ${stores.length-active}. Исторические записи не переписываются.</div></div><button class="btn primary" id="addStoreBtn">+ Добавить магазин</button></div><div class="toolbar store-toolbar"><input id="storeSearch" placeholder="Поиск магазина или менеджера"><select id="storeStatus"><option value="active">Активные</option><option value="all">Все</option><option value="closed">Закрытые</option></select></div><div id="storesArea"></div></div><div class="panel"><div class="muted small">PRIZ Control ${APP_VERSION} · серверная alpha-версия.</div></div>`;
  const renderStoreRows=()=>{const q=$('#storeSearch').value.toLowerCase().trim(),status=$('#storeStatus').value,list=stores.filter(s=>(status==='all'||(status==='active'&&s.active)||(status==='closed'&&!s.active))&&(!q||s.name.toLowerCase().includes(q)||(s.manager||'').toLowerCase().includes(q)));$('#storesArea').innerHTML=list.length?`<div class="table-wrap"><table class="stores-table"><thead><tr><th>Магазин</th><th>Менеджер</th><th>Статус</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.manager||'—')}</td><td>${s.active?'<span class="badge eval">АКТИВЕН</span>':'<span class="badge closed">ЗАКРЫТ</span>'}</td><td class="actions-cell"><button class="btn ghost small-btn edit-store" data-id="${esc(s.id)}">Изменить</button><button class="btn ${s.active?'danger':'ghost'} small-btn toggle-store" data-id="${esc(s.id)}">${s.active?'Закрыть':'Открыть'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><b>Ничего не найдено</b>Измени фильтр или поиск.</div>';$$('.edit-store').forEach(b=>b.onclick=()=>openStoreDialog(stores.find(s=>s.id===b.dataset.id),reg.code));$$('.toggle-store').forEach(b=>b.onclick=async()=>{const s=stores.find(x=>x.id===b.dataset.id);const next=!s.active;const {error}=await sb.from('stores').update({is_active:next,closed_at:next?null:nowISO()}).eq('id',s.id);if(error){toast(error.message,true);return}toast(next?'Магазин снова активен':'Магазин закрыт');renderSettings()})};
  $('#storeSearch').oninput=renderStoreRows;$('#storeStatus').onchange=renderStoreRows;$('#addStoreBtn').onclick=()=>openStoreDialog(null,reg.code);$('#addUserBtn').onclick=()=>openUserDialog(null);$$('.edit-user').forEach(b=>b.onclick=()=>openUserDialog(profileCache.find(u=>u.id===b.dataset.id)));renderStoreRows();
}

async function ensureManager(regionId,fullName){const name=String(fullName||'').trim();if(!name)return null;const {data:found,error:fErr}=await sb.from('managers').select('id,full_name').eq('region_id',regionId).ilike('full_name',name).limit(1);if(fErr)throw fErr;if(found?.[0])return found[0].id;const {data,error}=await sb.from('managers').insert({region_id:regionId,full_name:name,is_active:true}).select('id').single();if(error)throw error;return data.id}
function openStoreDialog(existing=null,regionCode=selectedRegionCode()){const reg=REGIONS[regionCode];$('#storeDialogBody').innerHTML=`<form id="storeForm" class="dialog-card"><div class="dialog-head"><div><h3>${existing?'Изменить магазин':'Новый магазин'}</h3><p class="muted">${esc(reg?.name||regionCode)}</p></div><button type="button" class="close-x">×</button></div><div class="form-grid"><label>Номер магазина<input name="number" value="${esc(existing?.number||'')}" placeholder="299" required></label><label>Название<input name="name" value="${esc(existing?.name||'')}" placeholder="299 Харьков" required></label><label class="full">Менеджер<input name="manager" value="${esc(existing?.manager||'')}" placeholder="Ф.И.О. менеджера" required></label><label class="toggle-label"><input name="active" type="checkbox" ${existing?.active===false?'':'checked'}><span>Магазин доступен для новых записей</span></label></div><div class="dialog-actions"><button type="button" class="btn ghost cancel">Отмена</button><button class="btn primary" id="storeSubmit" type="submit">Сохранить</button></div></form>`;const d=$('#storeDialog'),f=$('#storeForm');d.showModal();$('.close-x',f).onclick=()=>d.close();$('.cancel',f).onclick=()=>d.close();f.onsubmit=async e=>{e.preventDefault();const btn=$('#storeSubmit',f),fd=new FormData(f),number=fd.get('number').trim(),name=fd.get('name').trim(),manager=fd.get('manager').trim();setBusy(btn,true,'Сохраняем…');try{const managerId=await ensureManager(reg.id,manager),payload={region_id:reg.id,store_number:number,display_name:name,manager_id:managerId,is_active:!!fd.get('active'),closed_at:fd.get('active')?null:(existing?.closedAt||nowISO())};let error;if(existing)({error}=await sb.from('stores').update(payload).eq('id',existing.id));else({error}=await sb.from('stores').insert(payload));if(error)throw error;d.close();toast('Справочник обновлён');renderSettings()}catch(err){toast(err.message,true)}finally{setBusy(btn,false)}}}

async function invokeAdminUsers(body){const {data,error}=await sb.functions.invoke('admin-users',{body});if(error)throw error;if(data?.error)throw new Error(data.error);return data}
function openUserDialog(existing=null){
  const isEdit=!!existing;
  const selectedIds=['owner','boss'].includes(existing?.role)?[]:(existing?.region_ids?.length?existing.region_ids:(existing?.region_id?[existing.region_id]:[]));
  const regionChecks=Object.values(REGIONS).map(r=>`<label class="region-check"><input type="checkbox" name="regionIds" value="${esc(r.id)}" ${selectedIds.includes(r.id)?'checked':''}><span>${esc(r.name)}</span></label>`).join('');
  $('#userDialogBody').innerHTML=`<form id="userForm" class="dialog-card"><div class="dialog-head"><div><h3>${isEdit?'Изменить аккаунт':'Новый аккаунт'}</h3><p class="muted">Для оператора или старшего можно назначить от 1 до 3 регионов.</p></div><button type="button" class="close-x">×</button></div><div class="form-grid"><label>Ф.И.О.<input name="name" value="${esc(existing?.full_name||'')}" required></label><label>Логин<input name="login" value="${esc(existing?.username||'')}" ${isEdit?'readonly':''} placeholder="operator.kh" required></label><label>Пароль<input name="password" type="password" placeholder="${isEdit?'Оставь пустым, чтобы не менять':'Минимум 6 символов'}" ${isEdit?'':'required'}></label><label>Роль<select name="role"><option value="owner" ${existing?.role==='owner'?'selected':''}>Владелец</option><option value="boss" ${existing?.role==='boss'?'selected':''}>Руководитель</option><option value="senior" ${existing?.role==='senior'?'selected':''}>Старший оператор</option><option value="operator" ${!existing||existing?.role==='operator'?'selected':''}>Оператор</option></select></label><label class="full region-assign-wrap"><span>Регионы</span><div id="allRegionsNote" class="server-note hidden">Для владельца и руководителя автоматически доступны все регионы.</div><div id="regionAssignBox" class="region-assign-grid">${regionChecks}</div><div id="regionCountHint" class="file-hint"></div></label><label class="toggle-label"><input name="active" type="checkbox" ${existing?.is_active===false?'':'checked'}><span>Аккаунт активен</span></label></div><div class="dialog-actions"><button type="button" class="btn ghost cancel">Отмена</button><button class="btn primary" id="userSubmit" type="submit">Сохранить</button></div></form>`;
  const d=$('#userDialog'),f=$('#userForm'),roleSelect=f.elements.role;
  d.showModal();$('.close-x',f).onclick=()=>d.close();$('.cancel',f).onclick=()=>d.close();
  const syncRegionControls=()=>{
    const restricted=['senior','operator'].includes(roleSelect.value),boxes=$$('input[name="regionIds"]',f),checked=boxes.filter(x=>x.checked).length;
    $('#allRegionsNote',f).classList.toggle('hidden',restricted);$('#regionAssignBox',f).classList.toggle('hidden',!restricted);
    boxes.forEach(x=>x.disabled=!restricted||(checked>=3&&!x.checked));
    $('#regionCountHint',f).textContent=restricted?`Выбрано ${checked} из 3${checked===0?' · выбери хотя бы один':''}`:'Все регионы доступны автоматически';
  };
  roleSelect.onchange=syncRegionControls;
  $$('input[name="regionIds"]',f).forEach(box=>box.onchange=()=>{const checked=$$('input[name="regionIds"]:checked',f);if(checked.length>3){box.checked=false;toast('Можно назначить не больше 3 регионов',true)}syncRegionControls()});
  syncRegionControls();
  f.onsubmit=async e=>{e.preventDefault();const btn=$('#userSubmit',f),fd=new FormData(f),role=fd.get('role'),regionIds=fd.getAll('regionIds').map(String);if(['senior','operator'].includes(role)&&regionIds.length<1){toast('Для оператора/старшего выбери хотя бы один регион',true);return}if(regionIds.length>3){toast('Можно назначить не больше 3 регионов',true);return}setBusy(btn,true,'Сохраняем…');try{if(isEdit)await invokeAdminUsers({action:'update',id:existing.id,fullName:fd.get('name').trim(),password:fd.get('password'),role,regionIds,isActive:!!fd.get('active')});else await invokeAdminUsers({action:'create',username:fd.get('login').trim(),fullName:fd.get('name').trim(),password:fd.get('password'),role,regionIds});d.close();toast(isEdit?'Аккаунт обновлён':'Аккаунт создан');renderSettings()}catch(err){toast(err.message||'Не удалось сохранить аккаунт',true)}finally{setBusy(btn,false)}}
}

init().catch(e=>{console.error(e);alert('Ошибка запуска PRIZ Control: '+e.message)});
